"""Build the offline decision form from the maintained register. No server required."""
from pathlib import Path
import json

ROOT = Path(__file__).resolve().parents[1]
DATA = ROOT / 'docs/decisions/register.json'
data = json.loads(DATA.read_text())
rows = data['decisions']
assert len({r['id'] for r in rows}) == len(rows), 'Duplicate decision IDs'
assert {f'D{i:02}' for i in range(1, 75)} <= {r['id'] for r in rows}, 'Original decision missing'
for row in rows:
    assert row['status'] in data['statusMeaning']
    assert row['title'] and row['sourceFile'] and row['why']
    assert len({o['key'] for o in row['options']}) == len(row['options'])
    if row['status'] == 'confirmed':
        assert row['confirmed']['answer'] and row['confirmed']['source']
html = r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Business OS decision desk</title><style>
*{box-sizing:border-box}body{font:16px/1.55 var(--font-sans,system-ui,sans-serif);color:var(--foreground,#20252b);margin:0}h1{font-size:clamp(25px,4vw,36px);line-height:1.15;margin:12px 0}h2{font-size:24px;line-height:1.3;margin:12px 0 20px}h3{font-size:16px;margin:22px 0 6px}p{max-width:72ch}button,input,select,textarea{font:inherit}button,select,input,textarea{border:1px solid var(--border,#7b858f);border-radius:6px;padding:9px;color:inherit;background:var(--card,#fff)}button{cursor:pointer}button:hover{background:var(--secondary,#e8edf2)}:focus-visible{outline:3px solid var(--ring,#2866b4);outline-offset:3px}header{border-bottom:1px solid var(--border,#b8c0c8);padding-bottom:14px}.toolbar{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.toolbar input{flex:1;min-width:130px}.desk{display:grid;grid-template-columns:220px minmax(0,1fr);gap:26px;margin-top:20px}.list{max-height:620px;overflow:auto;padding:3px}.list button{display:block;width:100%;text-align:left;border:0;border-bottom:1px solid var(--border,#d3d9df);border-radius:0;font-size:14px;padding:10px 6px}.list button[aria-current=true]{background:var(--secondary,#e8edf2);font-weight:700}.muted{color:var(--muted-foreground,#52606d);font-size:14px}.choice{display:block;border:1px solid var(--border,#aeb8c3);border-radius:6px;padding:12px;margin:9px 0;cursor:pointer}.choice:has(input:checked){border-color:var(--ring,#2866b4);background:var(--secondary,#e8edf2)}.choice input{margin-right:8px}.detail{display:block;font-size:14px;margin:4px 0 0 27px;color:var(--muted-foreground,#52606d)}fieldset{padding:0;border:0;margin:0}legend{font-weight:600;margin-bottom:6px}textarea{width:100%;resize:vertical;min-height:85px;margin-top:6px}details{margin-top:16px;border-top:1px solid var(--border,#b8c0c8);padding-top:12px}summary{cursor:pointer}dl{font-size:14px}dt{font-weight:700}dd{margin:0 0 9px}#confirmation{padding:12px 16px;background:var(--secondary,#e8edf2);border-radius:6px}#message{font-size:14px;min-height:24px}.nav{display:flex;justify-content:space-between;gap:8px;margin:20px 0}footer{margin-top:20px;border-top:1px solid var(--border,#b8c0c8);padding-top:12px;font-size:14px}.hidden{display:none!important}#exportText{min-height:170px}label small{font-size:13px}@media(max-width:600px){.desk{display:block}.list{max-height:160px;border-bottom:1px solid var(--border,#aaa);margin-bottom:18px}h2{font-size:21px}.toolbar button{flex:1}.choice{padding:10px}.detail{margin-left:0}}@media(prefers-reduced-motion:no-preference){button{transition:background-color .12s ease-out}}@media print{aside,.toolbar,.nav,footer{display:none}.desk{display:block}}
</style></head><body><header><h1>Business OS decision desk</h1><p>Work through the P0–P4 choices. Recorded answers stay separate from your drafts. Recommendations are suggestions, not selected answers.</p><p id="stats" class="muted"></p><div class="toolbar"><label for="search" class="hidden">Search decisions</label><input id="search" type="search" placeholder="Search by ID, term or question" aria-label="Search decisions"><select id="phase" aria-label="Phase"><option value="">All phases</option><option>P0</option><option>P1</option><option>P2</option><option>P3</option><option>P4</option><option>Shared</option></select><select id="status" aria-label="Status"><option value="pending">Needs review</option><option value="">All statuses</option><option value="confirmed">Confirmed</option><option value="draft">My drafts</option></select></div></header><div class="desk"><aside><div id="list" class="list" aria-label="Question navigation"></div></aside><main id="question"><p id="meta" class="muted"></p><h2 id="title"></h2><div id="confirmation" class="hidden"></div><p id="why"></p><fieldset id="options"><legend>Your draft answer</legend><div id="choices"></div></fieldset><label for="custom">Your own answer or refinement</label><textarea id="custom" placeholder="Write a specific alternative, condition or refinement."></textarea><label for="notes">Notes, owner or timing</label><textarea id="notes" placeholder="Who should confirm this? What needs checking?"></textarea><h3>What this changes</h3><p id="effects"></p><h3>Benefits and tradeoffs</h3><p id="benefits"></p><div id="termsBox"><h3>Terms in this question</h3><dl id="terms"></dl></div><details><summary>Recommendation and source context</summary><p id="recommendation"></p><p id="owner"></p><p id="source" class="muted"></p><p id="evidence" class="muted"></p></details><div class="nav"><button id="previous">Previous question</button><button id="next">Next question</button></div></main></div><p id="message" role="status" aria-live="polite"></p><footer><div class="toolbar"><button id="export">Export draft answers</button><button id="copy">Show / copy answers</button><button id="import">Import saved drafts</button><input id="file" type="file" accept="application/json,.json" class="hidden"></div><p>Drafts stay in this browser when storage is available. They are not saved to Git, sent to an agent, or confirmed automatically. Export and return the answers for reconciliation. Do not enter passwords, keys or private financial identifiers. Changing a confirmed decision is a revision request until Kuu confirms it.</p><div id="exportPanel" class="hidden"><label for="exportText">Copy this export back to the agent</label><textarea id="exportText" readonly></textarea></div></footer>
<script id="register" type="application/json">__DATA__</script><script>
const data=JSON.parse(document.getElementById('register').textContent),rows=data.decisions,$=id=>document.getElementById(id);const key='bos-decision-drafts-v1';let drafts={},storage=true,current=null,visible=[];try{const x=JSON.parse(localStorage.getItem(key)||'{}');if(x&&typeof x==='object'&&!Array.isArray(x))drafts=x;}catch(e){storage=false;}const terms={'double entry':'Double-entry bookkeeping: each financial event creates balanced debit and credit entries.','chart of accounts':'The named list of accounting categories used when recording financial entries.',subledger:'A record of particular balances, such as unpaid customer invoices or supplier bills.',posting:'Recording a financial event as an accounting entry.',passkey:'A sign-in credential held by your device, usually unlocked with a fingerprint, face or device PIN.',percentile:'A value below which a stated share of measurements falls; the 95th percentile covers 95% of measurements.',VAT:'Value Added Tax: tax added to taxable sales; its timing and treatment need accountant confirmation.',TDS:'Tax Deducted at Source: tax withheld from a payment before the recipient receives it.',NPR:'Nepalese rupee: the currency used for the approval-limit comparison.',FX:'Foreign exchange: converting between currencies using a recorded rate.',BS:'Bikram Sambat: the Nepali calendar; fiscal-year numbering can differ from display dates.',AD:'Anno Domini: the Gregorian calendar year used in international date displays.',MFA:'Multi-factor authentication: signing in with more than one kind of proof, such as a password and a code.',OIDC:'OpenID Connect: the standard used to sign in through an identity provider.',ZITADEL:'The identity provider running login and identity membership for the system.',BullMQ:'A background-job library using Valkey to hold queued work.',Valkey:'An in-memory data store used for job queues and sessions.',CRM:'Customer Relationship Management: tracking leads, customers and selling activity.',PRD:'Product Requirements Document: the written requirements for product behavior.',BRD:'Business Requirements Document: the business needs the product must meet.',CPD:'Complete Product Documentation: one of the original product source documents.',ADR:'Architecture Decision Record: a written technical decision and its reasoning.',FK:'Foreign key: a database relationship that prevents references to missing records.',GUID:'Globally Unique Identifier: a generated identifier used to distinguish records.',RFQ:'Request for Quotation: asking suppliers for prices and terms.',PO:'Purchase Order: a formal commitment to buy from a vendor.',PR:'Purchase Request: an internal request to buy something, before placing the order.',AP:'Accounts Payable: money the company owes its suppliers.',AR:'Accounts Receivable: money customers owe the company.',IRD:'Inland Revenue Department: the Nepal tax authority; requirements need specialist confirmation.',CBMS:'Central Billing Monitoring System: Nepal tax billing reporting infrastructure; applicability needs accountant confirmation.',PMO:'Project Management Office: the project oversight function; the recorded role decision refines its name.',KPI:'Key Performance Indicator: a measure used to track a business or operational outcome.',ARR:'Annual Recurring Revenue: recurring revenue expressed as a yearly amount.',RAG:'Retrieval-Augmented Generation: an AI answer system that retrieves relevant documents before answering.',AI:'Artificial intelligence: software that can generate or classify information; data access still needs explicit scope.',CGNAT:'Carrier-Grade Network Address Translation: an ISP shares a public address across customers, which can prevent direct inbound access.',ISP:'Internet Service Provider: the company providing the internet connection.',TLS:'Transport Layer Security: encrypted network transport used by HTTPS.',API:'Application Programming Interface: the routes through which software calls another service.',UI:'User Interface: the screens and controls people interact with.',CI:'Continuous Integration: automated checks run when code changes.',ledger:'A financial record of postings or balances. A subledger tracks specific amounts owed without necessarily being full accounting.',snapshot:'A saved copy of the facts at a point in time, so later edits do not rewrite an earlier approval.',maker:'Maker-checker: one person prepares a sensitive change and another person approves it.',retention:'How long records or files are kept before an approved deletion policy applies.'};
function message(s){$('message').textContent=s;}function save(){try{localStorage.setItem(key,JSON.stringify(drafts));message('Draft saved in this browser. Export to share it.');}catch(e){storage=false;message('Browser storage is unavailable. Your draft is in memory; export before closing.');}stats();}
function stats(){$('stats').textContent=`${rows.length} items · 74 original decisions · ${rows.filter(r=>r.status==='confirmed').length} recorded answers · ${Object.keys(drafts).filter(id=>rows.some(r=>r.id===id)&&hasAnswer(drafts[id])).length} drafted. Register ${data.revision}.`;}function hasAnswer(d){return !!(d&&(d.choice||d.custom?.trim()||d.notes?.trim()));}
function rebuild(){const q=$('search').value.toLowerCase(),phase=$('phase').value,status=$('status').value;visible=rows.filter(r=>(!phase||r.phases.includes(phase))&&(!q||[r.id,r.title,r.why,r.group].join(' ').toLowerCase().includes(q))&&(!status||(status==='pending'?r.status!=='confirmed':status==='draft'?hasAnswer(drafts[r.id]):r.status===status)));const list=$('list');list.replaceChildren();for(const r of visible){const b=document.createElement('button');b.type='button';b.textContent=r.id+' · '+r.title;b.setAttribute('aria-current',String(r.id===current));b.onclick=()=>show(r.id);list.append(b);}if(!visible.length){$('question').classList.add('hidden');message('No questions match these filters.');return;}$('question').classList.remove('hidden');if(!visible.some(r=>r.id===current))current=visible[0].id;show(current);}
function show(id){current=id;const r=rows.find(r=>r.id===id),d=drafts[id]||{};$('title').textContent=r.title;$('meta').textContent=`${r.id} · ${r.phases.join(', ')} · ${r.status.replaceAll('-',' ')} · ${r.group}`;$('why').textContent=r.why.split(/(?<=[.!?])\s+/).slice(0,2).join(' ');$('confirmation').classList.toggle('hidden',!r.confirmed);$('confirmation').textContent=r.confirmed?`Recorded ${r.confirmed.date}: ${r.confirmed.answer} Effect: ${r.confirmed.effect}`:'';$('options').querySelector('legend').textContent=r.confirmed?'Draft a revision request (existing answer stays confirmed)':'Your draft answer';const choices=$('choices');choices.replaceChildren();for(const o of [...r.options,{key:'custom',label:'My own answer',detail:'Supply a different answer or conditions below.'}]){const l=document.createElement('label');l.className='choice';const input=document.createElement('input');input.type='radio';input.name='answer';input.value=o.key;input.checked=d.choice===o.key;input.onchange=()=>capture();l.append(input,document.createTextNode(o.label+(r.recommended===o.key?' · Suggested in source':'')));const detail=document.createElement('span');detail.className='detail';detail.textContent=o.detail;l.append(detail);choices.append(l);}$('custom').value=d.custom||'';$('notes').value=d.notes||'';explain();$('owner').textContent=r.needsOthers;$('recommendation').textContent=r.recommended?`Source recommendation ${r.recommended}: ${r.recommendationWhy}`:'No new recommendation is being made for this historical follow-up.';$('source').textContent=`Source: ${r.sourceFile}; ${r.sourceRefs.join(', ')}`;$('evidence').textContent='Implementation evidence: '+r.implementationStatus;const text=[r.title,r.why,r.blocks,...r.options.map(o=>o.label+' '+o.detail)].join(' ');$('terms').replaceChildren();let count=0;for(const [t,meaning]of Object.entries(terms)){const match=t===t.toUpperCase()?new RegExp('\\b'+t+'\\b').test(text):text.toLowerCase().includes(t.toLowerCase());if(match&&count++<8){const dt=document.createElement('dt'),dd=document.createElement('dd');dt.textContent=t;dd.textContent=meaning;$('terms').append(dt,dd);}}$('termsBox').classList.toggle('hidden',count===0);$('previous').disabled=visible.findIndex(r=>r.id===id)===0;$('next').disabled=visible.findIndex(r=>r.id===id)===visible.length-1;[...$('list').children].forEach(b=>b.setAttribute('aria-current',String(b.textContent.startsWith(id+' ·'))));stats();}
function explain(){const r=rows.find(r=>r.id===current),d=drafts[current]||{},o=r.options.find(o=>o.key===d.choice);$('effects').textContent=r.blocks;$('benefits').textContent=o?o.detail+' '+(r.recommendationWhy||''):'Choose an option to see its stated tradeoff. '+(r.recommendationWhy||'Custom answers should name the desired behavior and any conditions.');}
function capture(){drafts[current]={choice:document.querySelector('input[name=answer]:checked')?.value||'',custom:$('custom').value,notes:$('notes').value,updatedAt:new Date().toISOString()};save();explain();}
function exportData(){const answers=[];for(const r of rows){const d=drafts[r.id];if(!hasAnswer(d))continue;if((d.choice==='custom'||(r.id.startsWith('Q')&&d.choice==='B'))&&!d.custom?.trim()){show(r.id);message(r.id+': please supply your custom answer before exporting.');$('custom').focus();return null;}answers.push({id:r.id,question:r.title,choice:d.choice,choiceLabel:r.options.find(o=>o.key===d.choice)?.label||(d.choice==='custom'?'My own answer':''),custom:d.custom||'',notes:d.notes||'',kind:r.confirmed?'revision-request':'draft-answer'});}return JSON.stringify({schemaVersion:1,registerRevision:data.revision,exportedAt:new Date().toISOString(),status:'drafts-for-Kuu-confirmation',answers},null,2);}
$('custom').oninput=capture;$('notes').oninput=capture;['search','phase','status'].forEach(id=>$(id).addEventListener(id==='search'?'input':'change',rebuild));$('previous').onclick=()=>show(visible[visible.findIndex(r=>r.id===current)-1].id);$('next').onclick=()=>show(visible[visible.findIndex(r=>r.id===current)+1].id);$('export').onclick=()=>{const s=exportData();if(!s)return;const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([s],{type:'application/json'}));a.download='business-os-decision-drafts.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);message('Draft export downloaded. Return it for confirmation and register updates.');};$('copy').onclick=async()=>{const s=exportData();if(!s)return;$('exportPanel').classList.remove('hidden');$('exportText').value=s;try{await navigator.clipboard.writeText(s);message('Draft answers copied. Paste them back to the agent.');}catch(e){$('exportText').focus();$('exportText').select();message('Copy the selected export manually.');}};$('import').onclick=()=>$('file').click();$('file').onchange=async()=>{try{const f=$('file').files[0];if(!f)return;const x=JSON.parse(await f.text());if(x.schemaVersion!==1||!Array.isArray(x.answers))throw Error('Expected a version 1 draft export.');const next={...drafts},seen=new Set();for(const a of x.answers){if(seen.has(a.id))throw Error('Duplicate question ID: '+a.id);seen.add(a.id);const r=rows.find(r=>r.id===a.id);if(!r)throw Error('Unknown question ID: '+a.id);if(!r.options.some(o=>o.key===a.choice)&&!['','custom'].includes(a.choice))throw Error('Invalid option for '+a.id);if(typeof a.custom!=='string'||typeof a.notes!=='string')throw Error('Invalid text fields for '+a.id);next[a.id]={choice:a.choice,custom:a.custom,notes:a.notes};}drafts=next;save();rebuild();message('Imported drafts only; canonical decisions unchanged.'+(x.registerRevision!==data.revision?' Export revision differs; review each answer.':''));}catch(e){message('Import rejected: '+e.message);}};rebuild();if(!storage)message('Browser storage unavailable. Export drafts before closing.');
</script></body></html>'''
output = ROOT / 'docs/decisions/deliverable.html'
output.write_text(html.replace('__DATA__', json.dumps(data, ensure_ascii=False).replace('</', '<\\/')), encoding='utf8')
print(f'Built {len(rows)} decisions: {output}')
